    "help.settings.reset.how": "• 清除: 应用和网站的代理设置、网站 / 服务的出口开关、规则集开关、自定义规则集 / 软件 / 域名 / 解析、DNS、自动识别。\n• 官方规则重新从云端下载 (签名校验); 没联网时用这台电脑上已有的官方规则。\n• 应用会像第一次安装那样重新识别, 推荐设置来自官方规则。\n• 重置前自动备份, 做完可以撤销。",
