    "logs.diag.title": "向开发者上传诊断摘要",
    "logs.diag.desc": "登录后和出现异常时 (代理被自动关闭、系统代理被关、核心反复重启 …), 自动向 enana 官方云端上传一份诊断摘要, 方便开发者排查问题。摘要只有结构化的状态、判定和操作记录, 不含你访问的网站、应用名、IP 地址、服务器地址、密码和令牌; 云端 7 天后自动删除。",
    "logs.diag.aria": "上传诊断摘要",
    "logs.diag.onTitle": "开启诊断摘要上传",
    "logs.diag.onMsg": "开启后, 登录时和出现异常时会自动上传一份诊断摘要。",
    "logs.diag.onD1": "上传的内容: 版本、系统、接管方式、代理 / 核心 / 系统代理的状态、自动判定的原因、操作记录里的动作和状态码、服务器连通率 (服务器名已替换成编号)。",
    "logs.diag.onD2": "不包含: 网站、应用名、IP 地址、服务器地址、密码、令牌。云端最多保存 7 天, 到期自动删除, 随时可以在下面删除已上传的内容。",
    "logs.diag.offTitle": "关闭诊断摘要上传",
    "logs.diag.offMsg": "关闭后, 不再自动上传诊断摘要。",
    "logs.diag.offD1": "已经上传的内容会在 7 天内自动删除, 也可以现在就删除。关闭后遇到问题, 开发者看不到这台电脑的情况, 除非你手动发送完整诊断。",
    "logs.diag.onGo": "开启上传",
    "logs.diag.offGo": "关闭上传",
    "logs.diag.onDone": "已开启诊断摘要上传",
    "logs.diag.offDone": "已关闭诊断摘要上传",
    "logs.diag.sendTitle": "发送完整诊断给开发者",
    "logs.diag.sendDesc": "遇到摘要看不出来的问题时, 把最近的完整诊断 (含访问过的域名和应用名) 发给开发者, 会得到一个报告编号, 把编号告诉开发者即可。",
    "logs.diag.send": "发送完整诊断",
